sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var startDate = current.getValue('start_date');
    var endDate = current.getValue('end_date');

    // 1. From (start_date) is not after To (end_date)
    if (startDate && endDate) {
        if (startDate > endDate) {
            gs.addErrorMessage('Start Date (From) cannot be after End Date (To).');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Approved requests of the same type for one doctor do not overlap
    if (current.getValue('status') == 'approved' && !current.doctor.nil() && startDate && endDate) {
        var reqGr = new GlideRecord('x_2223823_apollo_0_doctor_request');
        reqGr.addQuery('doctor', current.getValue('doctor'));
        reqGr.addQuery('request_type', current.getValue('request_type'));
        reqGr.addQuery('status', 'approved');
        reqGr.addQuery('sys_id', '!=', current.getUniqueValue());

        // Date overlap formula: existing.start <= new.end AND existing.end >= new.start
        reqGr.addQuery('start_date', '<=', endDate);
        reqGr.addQuery('end_date', '>=', startDate);
        reqGr.setLimit(1);
        reqGr.query();

        if (reqGr.hasNext()) {
            var typeLabel = current.request_type.getDisplayValue() || current.getValue('request_type');
            gs.addErrorMessage('An approved ' + typeLabel + ' request already exists for this doctor overlapping the selected dates.');
            current.setAbortAction(true);
            return;
        }
    }

})(current, previous);
